<template><ElConfigProvider namespace="kel"><section class="native-flow-header"><header><div><button class="back" @click="emit('back')">← 作业平台</button><h1>{{name||'创建 Flow'}}<span :class="['state',state.toLowerCase()]">{{state}}</span></h1><div class="meta"><code>{{flow?.namespace||'Namespace 由项目确定'}}</code><span>{{project}}</span><span>{{flow?'Revision '+flow.revision:'New draft'}}</span></div></div><div class="actions"><KsButton :disabled="!canEdit" @click="emit('tab','Builder')">编辑 Flow</KsButton><KsButton type="primary" :disabled="!canExecute||!flow||flow.disabled||flow.draft" @click="emit('run')">Run</KsButton></div></header><nav v-if="flow"><button v-for="item in primary" :key="item[0]" :class="{active:tab===item[0]}" @click="emit('tab',item[0])">{{item[1]}}</button><select aria-label="更多 Flow 视图" :value="more.some(t=>t[0]===tab)?tab:''" @change="emit('tab',($event.target as HTMLSelectElement).value)"><option value="" disabled>更多</option><option v-for="item in more" :key="item[0]" :value="item[0]">{{item[1]}}</option></select><span v-if="dirty" class="dirty">● 未保存修改</span></nav></section></ElConfigProvider></template>
<script setup lang="ts">
import {computed} from 'vue';import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';
const props=defineProps<{name:string;flow?:any;project:string;tab:string;canEdit:boolean;canExecute:boolean;dirty:boolean}>(),emit=defineEmits(['back','tab','run']);const state=computed(()=>!props.flow?'NEW':props.flow.draft?'DRAFT':props.flow.disabled?'DISABLED':'ENABLED');
const primary=[['Overview','总览'],['Builder','编辑'],['Executions','执行'],['Triggers','触发器']],more=[['Revisions','版本'],['Dependencies','依赖'],['Logs','日志'],['Metrics','指标'],['Concurrency','并发与排队']];
</script>
<style scoped>.native-flow-header{font-family:var(--ks-font-family-sans);color:var(--ks-text-primary);background:var(--ks-bg-surface)}header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;gap:20px}h1{display:flex;align-items:center;gap:12px;font-size:22px;line-height:1.4;margin:7px 0}.back{font-size:11px;color:var(--ks-text-secondary)}.state{border:1px solid var(--ks-border-default);border-radius:4px;padding:3px 6px;color:var(--ks-text-secondary);font-size:9px;letter-spacing:.04em;font-weight:500}.state.enabled{color:#43b89b}.state.draft{color:#b496f8}.meta,.actions{display:flex;align-items:center;gap:14px}.meta{color:var(--ks-text-secondary);font-size:10px}nav{display:flex;gap:24px;height:46px;align-items:center;padding:0 20px;border-block:1px solid var(--ks-border-default);font-size:12px}nav>button{height:100%;color:var(--ks-text-secondary);border-bottom:2px solid transparent}nav>button.active{border-color:var(--ks-text-link);color:var(--ks-text-link)}select{background:var(--ks-bg-input);border:1px solid var(--ks-border-default);border-radius:4px;color:var(--ks-text-primary);padding:5px;font-size:11px}.dirty{margin-left:auto;font-size:10px;color:#c8a96f}</style>
